#!/usr/bin/env node
/**
 * crypto-parity.mjs — proves the BROWSER crypto module (js/crypto.js, running
 * on Node 24's native WebCrypto) and the Node mirror (cli/bootstrap.mjs) are
 * byte-for-byte SEMANTICALLY IDENTICAL, and pins both to KNOWN-ANSWER-TEST
 * vectors generated by an INDEPENDENT implementation (Python hashlib/hmac +
 * pycryptodome — see scripts/gen-kat.py in this repo; regenerate with
 * `python3 scripts/gen-kat.py`).
 *
 * This closes the audit gap where the suite only exercised the Node mirror
 * while shipping the browser module untested (AUDIT-WAVE-1 A2#3 / A4-F1).
 */
import {
  deriveKeys,
  importRowKey,
  encryptRow,
  decryptRow,
  rowAad,
  b64ToBytes,
  bytesToB64,
  hexToBytes,
  bytesToHex,
  u32be,
} from '../js/crypto.js';
import {
  buildBootstrapMaterial,
  deriveClientKeys,
  encryptRow as nodeEncryptRow,
  decryptRow as nodeDecryptRow,
  rowAad as nodeRowAad,
  buildRewrapMaterial,
  strictB64,
} from '../cli/bootstrap.mjs';
import { randomBytes } from 'node:crypto';

let pass = 0;
const fails = [];
function check(name, cond, detail) {
  if (cond) {
    pass++;
    console.log('  ok  ' + name);
  } else {
    fails.push(name + (detail !== undefined ? ' — ' + String(detail) : ''));
    console.log('  FAIL ' + name + (detail !== undefined ? ' — ' + String(detail) : ''));
  }
}
const hex = (b) => Buffer.from(b).toString('hex');
const buf = (b) => (Buffer.isBuffer(b) ? b : Buffer.from(b));

/* ---------------- KAT literals (independent Python reference) ---------------- */

const KAT = {
  password: 'kat-password-0123456789',
  saltHex: '00112233445566778899aabbccddeeff',
  iters: 100000,
  aes1Hex: '000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f',
  wrappedHex: '0102030405060708090a0b0c8b4f77faa7bf7b268d19ce49870d319ab9f442734fdf7fdc0d0e7ecd7553f5f59afb719e64b837d6f9abd707335e3514',
  kDataHex: '*SCRUBBED*<=',
  authUiHex: '*SCRUBBED*<=',
  authClockHex: '*SCRUBBED*<=',
  aadId: 'cal:20261030',
  aadVer: 7,
  aadHex: '63616c3a323032363130333000000007',
  aadUnicodeId: 'cal:\u{1f384}',
  aadUnicodeHex: '63616c3af09f8e8400000001',
  // Row-AEAD composition KAT (fixed K_data + AAD + fixed nonce -> ct):
  rowId: 'cal:20261030',
  rowVer: 7,
  rowNonceHex: '0a0b0c0d0e0f101112131415',
  rowCtHex: 'f27a79e21dd3ed636be2cdaeff19696db8c7299e3c2776ddb7f837f28390ad64cb91c2587f760a02a7ba541606cab554187547bbc649973c6937141f792a42a5559e8fa59d8c5dd23798487a215f1610fcb9faa20528fb74e65e0c82214d37694d80f7cfb7b0a7727587762014181967954d6f95c3170eaa0702129826d3e4e8af389914e8a06b9e7c3f',
  rowPayload: {
    events: [
      { id: 'w:11111111-2222-3333-4444-555555555555', date: '2026-11-01', hh: 8, mm: 30, title: 'KAT', priority: 1 },
    ],
  },
};
const katWrappedB64 = Buffer.from(KAT.wrappedHex, 'hex').toString('base64');

/* ---------------- 1. KAT: unlock derivation (browser path) ---------------- */

{
  const keys = await deriveKeys(KAT.password, KAT.saltHex, KAT.iters, katWrappedB64);
  check('KAT browser deriveKeys: AES1', hex(keys.aes1) === KAT.aes1Hex, hex(keys.aes1));
  check('KAT browser deriveKeys: K_data', hex(keys.kData) === KAT.kDataHex, hex(keys.kData));
  check('KAT browser deriveKeys: AUTH_UI', keys.authUiHex === KAT.authUiHex, keys.authUiHex);
}

/* ---------------- 2. KAT: unlock derivation (Node mirror) ---------------- */

{
  const keys = deriveClientKeys(KAT.password, KAT.saltHex, KAT.iters, katWrappedB64);
  check('KAT node deriveClientKeys: AES1', hex(keys.aes1) === KAT.aes1Hex);
  check('KAT node deriveClientKeys: K_data', hex(keys.kData) === KAT.kDataHex);
  check('KAT node deriveClientKeys: AUTH_UI', hex(keys.authUi) === KAT.authUiHex);
  check('KAT node deriveClientKeys: AUTH_CLOCK', hex(keys.authClock) === KAT.authClockHex);
}

/* ---------------- 3. KAT: AAD construction (both) ---------------- */

{
  check('KAT browser rowAad ASCII', hex(rowAad(KAT.aadId, KAT.aadVer)) === KAT.aadHex, hex(rowAad(KAT.aadId, KAT.aadVer)));
  check('KAT node rowAad ASCII', hex(nodeRowAad(KAT.aadId, KAT.aadVer)) === KAT.aadHex);
  check('KAT browser rowAad unicode (UTF-8)', hex(rowAad(KAT.aadUnicodeId, 1)) === KAT.aadUnicodeHex);
  check('KAT node rowAad unicode (UTF-8)', hex(nodeRowAad(KAT.aadUnicodeId, 1)) === KAT.aadUnicodeHex);
}

/* ---------------- 4. Random-material derivation parity ---------------- */

for (let i = 0; i < 3; i++) {
  const pw = 'parity-pw-' + i + '-' + randomBytes(8).toString('hex');
  const mat = buildBootstrapMaterial(pw, 100000);
  const b = await deriveKeys(pw, mat.saltHex, mat.iters, mat.wrappedB64);
  const n = deriveClientKeys(pw, mat.saltHex, mat.iters, mat.wrappedB64);
  check(
    `parity #${i}: browser == node (aes1/kData/authUi)`,
    hex(b.aes1) === hex(n.aes1) && hex(b.kData) === hex(n.kData) && b.authUiHex === hex(n.authUi)
  );
  check(`parity #${i}: derived AUTH_UI == CLI-registered token`, b.authUiHex === mat.authUiHex);
}

/* ---------------- 5. Envelope interop, both directions ---------------- */

{
  const mat = buildBootstrapMaterial('interop-pw', 100000);
  const nodeKeys = deriveClientKeys('interop-pw', mat.saltHex, mat.iters, mat.wrappedB64);
  const browserKeys = await deriveKeys('interop-pw', mat.saltHex, mat.iters, mat.wrappedB64);
  const rowKey = await importRowKey(browserKeys.kData);
  const payload = { events: [{ id: 'w:' + '11223344-5566-7788-99aa-bbccddeeff00', date: '2026-11-01', hh: 9, mm: 30, title: 'Interop', priority: 1 }] };

  for (const id of ['cal:20261101', 'cal:\u{1f384}', 'we/ird', 'cal:20991225']) {
    // Node encrypts -> browser decrypts
    {
      const enc = nodeEncryptRow(nodeKeys.kData, id, 3, payload);
      const out = await decryptRow(rowKey, id, 3, enc.nonce.toString('base64'), enc.ct.toString('base64'));
      check(`interop node->browser id=${JSON.stringify(id)}`, JSON.stringify(out) === JSON.stringify(payload));
    }
    // Browser encrypts -> Node decrypts
    {
      const enc = await encryptRow(rowKey, id, 3, payload);
      const out = nodeDecryptRow(nodeKeys.kData, id, 3, enc.nonce, enc.ct);
      check(`interop browser->node id=${JSON.stringify(id)}`, JSON.stringify(out) === JSON.stringify(payload));
    }
  }

  // §6 ver binding on the BROWSER path: wrong ver must fail AEAD.
  const enc = nodeEncryptRow(nodeKeys.kData, 'cal:20261101', 3, payload);
  let threw = false;
  try {
    await decryptRow(rowKey, 'cal:20261101', 4, enc.nonce.toString('base64'), enc.ct.toString('base64'));
  } catch {
    threw = true;
  }
  check('browser decryptRow at wrong ver throws (AAD binds ver)', threw);
}

/* ---------------- 6. Row-AEAD composition KAT (independent reference) ---------------- */

{
  const kData = Buffer.from(KAT.kDataHex, 'hex');
  const nonceB64 = Buffer.from(KAT.rowNonceHex, 'hex').toString('base64');
  const ctB64 = Buffer.from(KAT.rowCtHex, 'hex').toString('base64');

  // Node DECRYPT direction: the Python-produced ciphertext must decrypt to
  // the exact payload (pins K_data + AAD + ct||tag layout on the mirror).
  const nodeOut = nodeDecryptRow(kData, KAT.rowId, KAT.rowVer, nonceB64, ctB64);
  check(
    'KAT row composition: Node decrypt reproduces the payload',
    JSON.stringify(nodeOut) === JSON.stringify(KAT.rowPayload),
    JSON.stringify(nodeOut)
  );

  // Browser ENCRYPT direction: with the nonce source pinned to the KAT nonce
  // (temporary monkey-patch of crypto.getRandomValues — the ONLY caller of a
  // 12-byte buffer in encryptRow), the browser must reproduce the exact ct.
  {
    const rowKey = await importRowKey(new Uint8Array(kData));
    const real = crypto.getRandomValues.bind(crypto);
    crypto.getRandomValues = (arr) => {
      if (arr.length === 12) {
        arr.set(new Uint8Array(Buffer.from(KAT.rowNonceHex, 'hex')));
        return arr;
      }
      return real(arr);
    };
    let enc;
    try {
      enc = await encryptRow(rowKey, KAT.rowId, KAT.rowVer, KAT.rowPayload);
    } finally {
      crypto.getRandomValues = real;
    }
    check(
      'KAT row composition: browser encrypt reproduces the exact ct',
      enc.nonce === nonceB64 && enc.ct === ctB64,
      `nonce=${enc.nonce} ct=${enc.ct.slice(0, 24)}…`
    );
  }
}

/* ---------------- 7. Nonce freshness (§6: fresh random per write) ---------------- */

{
  const mat = buildBootstrapMaterial('nonce-freshness', 100000);
  const keys = await deriveKeys('nonce-freshness', mat.saltHex, mat.iters, mat.wrappedB64);
  const rowKey = await importRowKey(keys.kData);
  const seen = new Set();
  for (let i = 0; i < 200; i++) {
    const enc = await encryptRow(rowKey, 'cal:20261101', 1, { events: [] });
    seen.add(enc.nonce);
  }
  check('nonce freshness: 200 writes -> 200 distinct nonces', seen.size === 200, seen.size);
}

/* ---------------- 8. Strict-decoder parity (browser vs node vs server law) ---------------- */

{
  const bad = [
    '',                    // empty
    'AAA',                 // length % 4 != 0
    'A',                   // too short
    '!!!!',                // bad alphabet
    'QQ==',                // canonical 1 byte (VALID)
    'QR==',                // NON-canonical (trailing bits set)
    'QR=',                 // bad padding length
    'QQ',                  // unpadded
    'QQ==QQ==',            // padding mid-string
    'QUJD',                // canonical unpadded-length-4? "QUJD" decodes ABCD -> re-encodes "QUJD" (VALID, no padding needed)
    'QUJ=',                // canonical 3 bytes -> re-encode "QUJ=" (VALID)
    'QU==',                // canonical 2 bytes (VALID)
    'Q===',                // 3 pads — invalid
  ];
  const browser = bad.map((s) => {
    try { b64ToBytes(s); return 'ok'; } catch { return 'throw'; }
  });
  const node = bad.map((s) => {
    try { strictB64(s); return 'ok'; } catch { return 'throw'; }
  });
  // Expected per §5 (standard alphabet, padded, canonical). NOTE: 'QUJ=' and
  // 'QU==' are NON-canonical (trailing padding bits nonzero: canonical forms
  // are 'QUI=' and 'QQ==' respectively; 'QUJD' decodes to the 3 bytes "ABC").
  // Verified against Node + Python.
  const expected = ['throw', 'throw', 'throw', 'throw', 'ok', 'throw', 'throw', 'throw', 'throw', 'ok', 'throw', 'throw', 'throw'];
  check('b64 strictness parity browser==node', JSON.stringify(browser) === JSON.stringify(node), JSON.stringify({ browser, node }));
  check('b64 strictness matches §5 law', JSON.stringify(browser) === JSON.stringify(expected), JSON.stringify(browser));
}

/* ---------------- 7. Encoding helper parity across sizes ---------------- */

{
  let allOk = true;
  for (const n of [0, 1, 2, 3, 12, 16, 64, 255, 256, 1000, 65536]) {
    const data = randomBytes(n);
    const bb = bytesToB64(new Uint8Array(data));
    const nb = data.toString('base64');
    if (bb !== nb) allOk = false;
    if (n > 0) {
      const back = b64ToBytes(bb);
      if (hex(back) !== hex(data)) allOk = false;
    }
  }
  check('bytesToB64/b64ToBytes parity with Node across sizes 0..65536', allOk);
}
{
  let allOk = true;
  for (const n of [1, 16, 32, 33]) {
    const data = randomBytes(n);
    if (bytesToHex(new Uint8Array(data)) !== data.toString('hex')) allOk = false;
    if (hex(hexToBytes(data.toString('hex'))) !== hex(data)) allOk = false;
  }
  check('bytesToHex/hexToBytes parity with Node', allOk);
}
{
  // u32be is a generic u32 encoder: 0 is a VALID u32; only non-integer /
  // negative / >u32 values throw (4 of the 5 below).
  let u32throws = 0;
  for (const v of [-1, 0, 1.5, '2', 4294967296]) {
    try { u32be(v); } catch { u32throws++; }
  }
  check('u32be rejects non-u32 values (0 is a valid u32)', u32throws === 4, u32throws);
  // rowAad enforces the §2 row-ver law (u32 >= 1) in BOTH implementations.
  let raThrows = 0;
  for (const v of [-1, 0, 1.5, '2', 4294967296]) {
    try { nodeRowAad('cal:20261101', v); } catch { raThrows++; }
    try { rowAad('cal:20261101', v); } catch { raThrows++; }
  }
  check('rowAad (browser + node) rejects ver < 1 and non-u32', raThrows === 10, raThrows);
}

/* ---------------- 8. Type A rewrap material keeps AES1 ---------------- */

{
  const mat = buildBootstrapMaterial('old-pw', 100000);
  const re = buildRewrapMaterial(mat.aes1, 'new-pw', 100000);
  const after = deriveClientKeys('new-pw', re.saltHex, 100000, re.wrappedB64);
  check('Type A rewrap: new password unwraps the SAME AES1', after.aes1.equals(mat.aes1));
  const browserAfter = await deriveKeys('new-pw', re.saltHex, 100000, re.wrappedB64);
  check('Type A rewrap: browser path agrees (AES1 unchanged)', hex(browserAfter.aes1) === mat.aes1Hex);
  check(
    'Type A rewrap: AUTH tokens unchanged (HKDF of the same AES1)',
    hex(after.authUi) === mat.authUiHex && hex(after.authClock) === mat.authClockHex
  );
}

console.log(`\ncrypto-parity: ${pass} passed, ${fails.length} failed`);
if (fails.length) {
  for (const f of fails) console.error('  FAIL ' + f);
  process.exit(1);
}
